        "day2": "سوال نمبر چھ: دیے ہوئے جملوں میں سے اسم اور فعل الگ کر کے سامنے خانوں میں لکھیں - سوال نمبر سات: درست جواب کے خانے کو پینسل سے بھریں۔",
        "day3": "سوال نمبر آٹھ: درج ذیل تصویر کو دیکھ کر کم سے کم پانچ سے سات جملے لکھیں۔ - سوال نمبر۔ نو: کھانے کے اداب کے موضوع پر اپنے ساتھی طلبہ کے سامنے دو سے تین جملوں میں اپنے خیالات کا اظہار کریں۔",
        "day4": "سوال نمبر دس: حوالدار لالک جان کی شہادت کا پورا واقعہ درست تلفظ اور لب و لہجے کے ساتھ بیان کریں۔",
